//! The transistor families (DSP.md E1, E2) through `Circuit<Dk>` on the
//! very decks ngspice simulates (`spice/*.cir`, generated by
//! `scripts/ngspice-simulate.py`): the DC families of curves first —
//! every point a DC solution, so model and simulator should agree to
//! the solver tolerances — then real circuits, each with its own
//! stimulus, as `stave_test::reference::Case`s with explicit budgets.
//! Every solve's health is printed and no solve may hit its cap.

use std::path::PathBuf;

use stave_dsp::circuit::devices::bjt::{EbersMoll, GummelPoon, Polarity};
use stave_dsp::circuit::devices::diode::THERMAL_VOLTS_27C;
use stave_dsp::circuit::methods::dk::{Dk, Health};
use stave_dsp::circuit::netlist::{ElementKind, Netlist};
use stave_dsp::circuit::Circuit;
use stave_test::reference::{assert_converges, Case, Metric, Outcome, Reference};

fn deck(name: &str) -> Netlist {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(format!("spice/{name}.cir"));
    Netlist::parse_spice(&std::fs::read_to_string(&path).unwrap()).unwrap()
}

/// The deck's own stimulus at `oversample` × 48 kHz, read at the
/// reference's instants (sample 0 is the operating point).
fn transient(netlist: &Netlist, name: &str, oversample: u32) -> (Vec<f64>, Health) {
    let reference = Reference::ngspice(name);
    let rate = 48_000.0 * f64::from(oversample);
    let mut circuit = Circuit::<Dk>::new(netlist).unwrap();
    circuit.prepare(rate as f32);
    let (mut n, mut out) = (0u64, circuit.output());
    let run = reference
        .abscissa()
        .iter()
        .map(|&t| {
            while n < (t * rate).round() as u64 {
                out = circuit.step(0.0);
                n += 1;
            }
            out
        })
        .collect();
    (run, circuit.health())
}

fn healthy(name: &str, health: &Health) {
    println!(
        "  DK solve: {:.2} iterations/solve, {} of {} capped, {} continuations",
        health.newton.mean_iterations(),
        health.newton.capped,
        health.newton.solves,
        health.continuations
    );
    assert_eq!(health.newton.capped, 0, "{name} hit its iteration cap");
}

fn case(name: &str, oversample: u32, metric: Metric, budget: f64) -> Outcome {
    let (run, health) = transient(&deck(name), name, oversample);
    let outcome = Case::ngspice(name)
        .named(format!("{name}/dk {oversample}x"))
        .budget(metric, budget)
        .compare(&run);
    healthy(name, &health);
    outcome
}

// ------------------------------------------------------------ DC families

/// 2N3904, Ic(Vce) at five base currents: Gummel–Poon with Early
/// effect, roll-off, leakage and RB/RC, against ngspice's `bjtload.c`.
#[test]
fn bjt_family_matches_ngspice() {
    case("bjt_family", 1, Metric::NormalizedRms, 2e-6).assert();
}

/// AC128 (germanium PNP), Ic(Vce) at five base currents, at the card's
/// Vt = 25.5 mV; the deck's card reads as `GummelPoon::AC128`.
#[test]
fn bjt_family_pnp_matches_ngspice() {
    let netlist = deck("bjt_family_pnp");
    let Some(ElementKind::Bjt { bjt, .. }) = netlist.element("q1").map(|e| &e.kind) else {
        panic!("no Q1")
    };
    let card = GummelPoon::AC128;
    let fields = |q: &GummelPoon| {
        [
            q.saturation_amps,
            q.forward_beta,
            q.reverse_beta,
            q.forward_emission,
            q.reverse_emission,
            q.forward_early_volts,
            q.reverse_early_volts,
            q.forward_knee_amps,
            q.reverse_knee_amps,
            q.emitter_leakage_amps,
            q.emitter_leakage_emission,
            q.collector_leakage_amps,
            q.collector_leakage_emission,
            q.base_ohms,
            q.emitter_ohms,
            q.collector_ohms,
            q.thermal_volts,
        ]
    };
    assert_eq!(bjt.polarity, card.polarity);
    for (read, published) in fields(bjt).into_iter().zip(fields(&card)) {
        assert!((read - published).abs() <= 1e-6 * published.abs(), "{read} vs {published}");
    }
    case("bjt_family_pnp", 1, Metric::NormalizedRms, 5e-7).assert();
}

/// A card with only IS, BF and BR is Ebers–Moll: it reads as
/// `GummelPoon::from(EbersMoll)` (whose currents are `EbersMoll`'s to
/// 1e-12, `devices::bjt` unit tests), into reverse active at the end.
#[test]
fn ebers_moll_matches_ngspice() {
    let netlist = deck("bjt_family_em");
    let Some(ElementKind::Bjt { bjt, .. }) = netlist.element("q1").map(|e| &e.kind) else {
        panic!("no Q1")
    };
    let em = EbersMoll {
        polarity: Polarity::N,
        saturation_amps: 1e-14,
        forward_beta: 200.0,
        reverse_beta: 2.0,
        thermal_volts: THERMAL_VOLTS_27C,
    };
    assert_eq!(*bjt, GummelPoon::from(em));
    case("bjt_family_em", 1, Metric::NormalizedRms, 5e-7).assert();
}

